#include <cstddef>
#include <cstdint>
#include <cstring>

// SDK XAudio source implementation, not RAGE physics despite the autogenerated
// ph_vt5A60_56_7D90 symbol. Names below describe observed roles, not recovered symbols.
struct XAudioLock {
    uint32_t spin;
    uint32_t depth;
    void* owner;
    uint8_t oldIrql;
    uint8_t pad[3];
};

struct AudioFrame {
    uint8_t format;
    uint8_t channels;
    uint16_t pad;
    uint32_t sampleRate;
    float* samples;
};

struct XmaRenderStream {
    const void* input;
    uint32_t inputFrames;
    uint32_t inputOffset;
    uint8_t format;
    uint8_t channels;
    uint8_t pad0[6];
    float* output;
    uint32_t outputFrames;
    uint32_t outputOffset;
    uint32_t unknown20;
    float previousGain;
    float gain;
    uint32_t unknown2c;
    float filterGain;
    uint32_t filterHistory[6];
    uint8_t pad1[12];
};

struct SourceLink {
    SourceLink* next;
    SourceLink* previous;
};

struct XmaSourceLayout {
    void** vtable;
    uint8_t pad04[12];
    void** sourceVtable;                   // +0x10: secondary interface
    SourceLink buffers;                     // +0x14: intrusive sentinel
    uint32_t linkOffset;                    // +0x1c: link offset within buffer objects
    uint8_t pad20[20];
    uint8_t streamCount;                    // +0x34
    uint8_t pad35[3];
    struct { uint32_t unknown; uint8_t channels; uint8_t pad[3]; } formats[6];
    uint8_t pad68[4];
    float gain;                            // +0x6c
    uint8_t pad70[52];
    uint32_t samplesPlayed;                 // +0xa4
    uint8_t flags;                          // +0xa8: playing/reset/fade/ending/stopped
    uint8_t padA9;
    uint16_t fadeTicks;                     // +0xaa
    uint8_t padAC[8];
    void* decoder;                          // +0xb4
    XmaRenderStream* streams;               // +0xb8
    uint8_t padBC[62];
    uint16_t refillThreshold[7];            // +0xfa
    XAudioLock lock;                        // +0x108
};

#if UINTPTR_MAX == UINT32_MAX
static_assert(sizeof(AudioFrame) == 12);
static_assert(sizeof(XmaRenderStream) == 88);
static_assert(offsetof(XmaSourceLayout, gain) == 108);
static_assert(offsetof(XmaSourceLayout, decoder) == 180);
static_assert(offsetof(XmaSourceLayout, refillThreshold) == 250);
static_assert(offsetof(XmaSourceLayout, lock) == 264);
#endif

extern "C" uint32_t KeRaiseIrqlToDpcLevel();                    // @ 0x8258653C
extern "C" void KeAcquireSpinLockAtRaisedIrql(uint32_t* lock);  // @ 0x8258634C
extern "C" void KeReleaseSpinLockFromRaisedIrql(uint32_t* lock);// @ 0x8258631C
extern "C" void KfLowerIrql(uint32_t irql);                     // @ 0x8258654C
extern void* g_sda_base; // Host representation of the Xbox r13 thread/PCR identity.
extern XAudioLock g_xaudioSourceLock;                          // @ 0x825E7870
extern const float g_xmaFadeScale;                             // @ 0x82005A5C

int32_t XAudioFrame_Get(void* buffer, AudioFrame* frame);        // @ 0x82465DA8
int32_t XAudioFrame_Resize(void* buffer, const AudioFrame* frame, uint32_t flags); // @ 0x82466018
int32_t XmaDecoder_IsEnabled(void* decoder);                    // @ 0x8246AEF8
int32_t XmaDecoder_Lock(void* decoder);                         // @ 0x8246B708
void XmaDecoder_Wait(void* decoder);                            // @ 0x8246B7A0
uint32_t XmaDecoder_Available(void* decoder, uint32_t stream);   // @ 0x8246B118
uint32_t XmaDecoder_Peek(void* decoder, uint32_t stream, const void** input); // @ 0x8246B360
uint32_t XmaRenderStream_Process(XmaRenderStream* stream);       // @ 0x82470CC0
void XmaDecoder_Consume(void* decoder, uint32_t stream, uint32_t frames, const void** input); // @ 0x8246B190
uint32_t XmaDecoder_SamplesPlayed(void* decoder, uint32_t stream);// @ 0x8246B550
int32_t XmaSource_SubmitBuffers(void* source);                   // @ 0x82467278
int32_t XmaDecoder_Unlock(void* decoder);                       // @ 0x8246B9E0

// Render one 256-frame planar float block, padding underruns and retiring buffers.
// r4 is unused; r5 is the output frame interface. This is vtable slot 56 of
// 0x82005a60, not a physics update. Locks are explicitly dropped around callbacks.
int32_t XmaSource_Render(XmaSourceLayout* self, void*, void* output) { // @ 0x82467D90
    auto acquire = [](XAudioLock& lock) {
        uint32_t irql = KeRaiseIrqlToDpcLevel();
        if (lock.depth == 0 || lock.owner != g_sda_base) {
            KeAcquireSpinLockAtRaisedIrql(&lock.spin);
            lock.owner = g_sda_base;
            lock.oldIrql = static_cast<uint8_t>(irql);
        }
        ++lock.depth;
    };
    auto release = [](XAudioLock& lock) {
        if (lock.depth != 0 && lock.owner == g_sda_base) {
            if (--lock.depth == 0) {
                uint32_t irql = lock.oldIrql;
                lock.owner = nullptr;
                lock.oldIrql = 0;
                KeReleaseSpinLockFromRaisedIrql(&lock.spin);
                KfLowerIrql(irql);
            }
        }
    };
    auto setFlags = [self](uint32_t mask, uint32_t value) {
        using Fn = void (*)(void*, uint32_t, uint32_t);
        reinterpret_cast<Fn>(self->sourceVtable[17])(&self->sourceVtable, mask, value);
    };
    auto stop = [self]() {
        using Fn = void (*)(void*, uint32_t);
        reinterpret_cast<Fn>(self->vtable[11])(self, 1);
    };
    auto nextBuffer = [self](void* buffer) -> void* {
        auto* sentinel = &self->buffers;
        auto* link = buffer ? reinterpret_cast<SourceLink*>(static_cast<uint8_t*>(buffer) + self->linkOffset)
                            : sentinel;
        return link->next == sentinel ? nullptr
            : reinterpret_cast<uint8_t*>(link->next) - self->linkOffset;
    };

    acquire(self->lock);
    if (!XmaDecoder_IsEnabled(self->decoder)) {
        release(self->lock);
        return 0;
    }
    int32_t result = XmaDecoder_Lock(self->decoder);
    if (result < 0) {
        release(self->lock);
        return result;
    }

    acquire(g_xaudioSourceLock);
    AudioFrame frame;
    result = XAudioFrame_Get(output, &frame);
    if (result >= 0) {
        uint32_t channels = 0;
        for (uint8_t i = 0; i < self->streamCount; ++i) channels += self->formats[i].channels;
        frame.channels = static_cast<uint8_t>(channels);
        result = XAudioFrame_Resize(output, &frame, 1);
    }
    if (result < 0) {
        release(g_xaudioSourceLock);
        release(self->lock);
        return result;
    }
    for (uint8_t i = 0; i < self->streamCount; ++i) {
        auto& stream = self->streams[i];
        stream.output = frame.samples;
        stream.outputFrames = 256;
        stream.outputOffset = 0;
        frame.samples += self->formats[i].channels * 256;
    }

    if (!(self->flags & 1) || (self->flags & 16)) {
        for (uint8_t i = 0; i < self->streamCount; ++i) {
            auto& stream = self->streams[i];
            for (uint32_t channel = 0; channel < stream.channels; ++channel) {
                std::memset(stream.output + channel * 256, 0, stream.outputFrames * sizeof(float));
            }
        }
        release(g_xaudioSourceLock);
        release(self->lock);
        return 1;
    }
    if (self->flags & 2) {
        for (uint8_t i = 0; i < self->streamCount; ++i) {
            auto& stream = self->streams[i];
            stream.gain = self->gain;
            stream.previousGain = stream.gain;
            for (auto& value : stream.filterHistory) value = 0;
            stream.filterGain = 0.0f;
        }
        setFlags(2, 0);
    }
    if (self->flags & 4) {
        --self->fadeTicks; // uint16 wrap is intentional, including zero -> 65535.
        float gain = self->fadeTicks ? self->streams[0].gain * g_xmaFadeScale : 0.0f;
        for (uint8_t i = 0; i < self->streamCount; ++i) self->streams[i].gain = gain;
    }
    release(g_xaudioSourceLock);

    XmaDecoder_Wait(self->decoder);
    uint32_t silence = 0;
    bool refill = false;
    for (uint8_t i = 0; i < self->streamCount; ++i) {
        uint32_t available = XmaDecoder_Available(self->decoder, i);
        uint32_t consumed = 0;
        const void* input;
        if (available) {
            uint32_t count = XmaDecoder_Peek(self->decoder, i, &input);
            while (count) {
                auto& stream = self->streams[i];
                stream.input = input;
                stream.inputFrames = count;
                stream.inputOffset = 0;
                uint32_t processed = XmaRenderStream_Process(&stream);
                consumed += processed;
                XmaDecoder_Consume(self->decoder, i, processed, &input);
                if (self->streams[i].outputFrames == self->streams[i].outputOffset) break;
                count = XmaDecoder_Peek(self->decoder, i, &input);
            }
        }
        if (available - consumed <= self->refillThreshold[i]) refill = true;
        self->samplesPlayed = XmaDecoder_SamplesPlayed(self->decoder, 0);
        auto& stream = self->streams[i];
        uint32_t remaining = stream.outputFrames - stream.outputOffset;
        if (remaining) {
            // r26 holds the byte count in the channel loop, then becomes 1.
            for (uint32_t channel = 0; channel < stream.channels; ++channel) {
                std::memset(stream.output + stream.outputOffset + channel * 256, 0, remaining * sizeof(float));
            }
            silence = 1;
        }
    }
    int32_t submitted = XmaSource_SubmitBuffers(self);
    acquire(g_xaudioSourceLock);
    for (uint8_t i = 0; i < self->streamCount; ++i) self->streams[i].previousGain = self->streams[i].gain;

    if (silence) {
        if (!(self->flags & 8)) {
            bool pending = false;
            for (void* buffer = nextBuffer(nullptr); buffer; buffer = nextBuffer(buffer)) {
                pending |= static_cast<uint8_t*>(buffer)[96] != 4;
            }
            if (!pending) setFlags(16, 16);
        } else if (submitted == 0 && !(self->flags & 16)) {
            stop();
        }
    }
    if ((self->flags & 4) && (self->fadeTicks == 0 || (self->flags & 16))) stop();

    if (!(self->flags & 1) || (self->flags & 16)) {
        for (void* buffer = nextBuffer(nullptr); buffer;) {
            void* current = buffer;
            buffer = nextBuffer(buffer); // callbacks may unlink/free current
            if (static_cast<uint8_t*>(current)[96] != 4) continue;
            release(g_xaudioSourceLock);
            release(self->lock);
            using Fn = void (*)(void*, void*, uint32_t);
            reinterpret_cast<Fn>(self->sourceVtable[19])(&self->sourceVtable, current, 0);
            acquire(self->lock);
            acquire(g_xaudioSourceLock);
        }
    }
    release(g_xaudioSourceLock);
    if (refill && XmaDecoder_IsEnabled(self->decoder)) {
        result = XmaDecoder_Unlock(self->decoder);
        if (result < 0) {
            release(self->lock);
            return result;
        }
    }
    release(self->lock);
    return 0;
}
